using System.Security.Cryptography;
using System.Text;
using System.Text.Json;

namespace Payments;

public interface IPaymentProvider
{
    Task<ProviderChargeResult> CreateChargeAsync(string cardToken, decimal amount);
    Task<ProviderRefundResult> CreateRefundAsync(string chargeId);
}

public sealed class PaymentGateway
{
    private readonly IPaymentProvider _provider;
    private readonly string _webhookSecret;

    public PaymentGateway(IPaymentProvider provider, string webhookSecret)
    {
        _provider = provider ?? throw new ArgumentNullException(nameof(provider));
        _webhookSecret = webhookSecret ?? throw new ArgumentNullException(nameof(webhookSecret));
    }

    public async Task<ChargeResult> ChargeAsync(string cardToken, decimal amount)
    {
        if (string.IsNullOrWhiteSpace(cardToken))
            throw new ArgumentException("Card token is required.", nameof(cardToken));
        if (amount <= 0)
            throw new ArgumentOutOfRangeException(nameof(amount), "Amount must be positive.");
        if (amount > 999_999.99m)
            throw new ArgumentOutOfRangeException(nameof(amount), "Amount exceeds maximum.");

        var result = await _provider.CreateChargeAsync(cardToken, amount);
        return new ChargeResult(result.Id, result.Status == "succeeded");
    }

    public async Task<RefundResult> RefundAsync(string chargeId)
    {
        if (string.IsNullOrWhiteSpace(chargeId))
            throw new ArgumentException("Charge ID is required.", nameof(chargeId));

        var result = await _provider.CreateRefundAsync(chargeId);
        return new RefundResult(result.Id, result.Status == "succeeded");
    }

    public WebhookEvent ProcessWebhook(string payload, string signature)
    {
        if (string.IsNullOrWhiteSpace(payload))
            throw new ArgumentException("Payload is required.", nameof(payload));
        if (string.IsNullOrWhiteSpace(signature))
            throw new ArgumentException("Signature is required.", nameof(signature));

        var expectedSignature = ComputeSignature(payload);
        if (!string.Equals(expectedSignature, signature, StringComparison.Ordinal))
            throw new InvalidOperationException("Invalid webhook signature.");

        var webhookEvent = JsonSerializer.Deserialize<WebhookEvent>(payload)
            ?? throw new InvalidOperationException("Failed to deserialize webhook payload.");

        return webhookEvent;
    }

    private string ComputeSignature(string payload)
    {
        var keyBytes = Encoding.UTF8.GetBytes(_webhookSecret);
        var payloadBytes = Encoding.UTF8.GetBytes(payload);
        var hash = HMACSHA256.HashData(keyBytes, payloadBytes);
        return Convert.ToHexStringLower(hash);
    }
}

public record ChargeResult(string ChargeId, bool Success);
public record RefundResult(string RefundId, bool Success);
public record ProviderChargeResult(string Id, string Status);
public record ProviderRefundResult(string Id, string Status);
public record WebhookEvent(string Type, string ResourceId);

