using System.Security.Cryptography;
using System.Text;
using System.Text.Json;
using NSubstitute;
using Payments;

namespace PaymentGateway.Tests;

[TestClass]
public sealed class PaymentGatewayTests
{
    private readonly IPaymentProvider _provider;
    private readonly Payments.PaymentGateway _gateway;
    private const string WebhookSecret = "test-secret-key";

    public PaymentGatewayTests()
    {
        _provider = Substitute.For<IPaymentProvider>();
        _gateway = new Payments.PaymentGateway(_provider, WebhookSecret);
    }

    #region Constructor validation

    [TestMethod]
    public void Constructor_NullProvider_Throws()
    {
        var ex = Assert.ThrowsExactly<ArgumentNullException>(
            () => new Payments.PaymentGateway(null!, WebhookSecret));
        Assert.AreEqual("provider", ex.ParamName);
    }

    [TestMethod]
    public void Constructor_NullWebhookSecret_Throws()
    {
        var ex = Assert.ThrowsExactly<ArgumentNullException>(
            () => new Payments.PaymentGateway(_provider, null!));
        Assert.AreEqual("webhookSecret", ex.ParamName);
    }

    #endregion

    #region ChargeAsync — success

    [TestMethod]
    public async Task ChargeAsync_ValidInput_ReturnsSuccessResult()
    {
        _provider.CreateChargeAsync("tok_valid", 50.00m)
            .Returns(new ProviderChargeResult("ch_123", "succeeded"));

        var result = await _gateway.ChargeAsync("tok_valid", 50.00m);

        Assert.AreEqual("ch_123", result.ChargeId);
        Assert.IsTrue(result.Success);
    }

    [TestMethod]
    public async Task ChargeAsync_ProviderDeclines_ReturnsFailureResult()
    {
        _provider.CreateChargeAsync("tok_bad", 10.00m)
            .Returns(new ProviderChargeResult("ch_456", "failed"));

        var result = await _gateway.ChargeAsync("tok_bad", 10.00m);

        Assert.AreEqual("ch_456", result.ChargeId);
        Assert.IsFalse(result.Success);
    }

    [TestMethod]
    [DataRow(0.01)]
    [DataRow(999_999.99)]
    public async Task ChargeAsync_BoundaryAmounts_Succeeds(double amount)
    {
        var decimalAmount = (decimal)amount;
        _provider.CreateChargeAsync("tok_ok", decimalAmount)
            .Returns(new ProviderChargeResult("ch_edge", "succeeded"));

        var result = await _gateway.ChargeAsync("tok_ok", decimalAmount);

        Assert.IsTrue(result.Success);
    }

    #endregion

    #region ChargeAsync — validation

    [TestMethod]
    [DataRow(null)]
    [DataRow("")]
    [DataRow("   ")]
    public async Task ChargeAsync_InvalidCardToken_ThrowsArgumentException(string? cardToken)
    {
        var ex = await Assert.ThrowsExactlyAsync<ArgumentException>(
            async () => await _gateway.ChargeAsync(cardToken!, 10m));
        Assert.AreEqual("cardToken", ex.ParamName);
    }

    [TestMethod]
    [DataRow(0)]
    [DataRow(-1)]
    [DataRow(-100.50)]
    public async Task ChargeAsync_NonPositiveAmount_ThrowsArgumentOutOfRange(double amount)
    {
        var ex = await Assert.ThrowsExactlyAsync<ArgumentOutOfRangeException>(
            async () => await _gateway.ChargeAsync("tok_ok", (decimal)amount));
        Assert.AreEqual("amount", ex.ParamName);
    }

    [TestMethod]
    public async Task ChargeAsync_AmountExceedsMaximum_ThrowsArgumentOutOfRange()
    {
        var ex = await Assert.ThrowsExactlyAsync<ArgumentOutOfRangeException>(
            async () => await _gateway.ChargeAsync("tok_ok", 1_000_000.00m));
        Assert.AreEqual("amount", ex.ParamName);
    }

    #endregion

    #region ChargeAsync — provider errors

    [TestMethod]
    public async Task ChargeAsync_ProviderThrows_PropagatesException()
    {
        _provider.CreateChargeAsync(Arg.Any<string>(), Arg.Any<decimal>())
            .ThrowsAsync(new HttpRequestException("Network error"));

        await Assert.ThrowsExactlyAsync<HttpRequestException>(
            async () => await _gateway.ChargeAsync("tok_ok", 25m));
    }

    #endregion

